
const canvas=document.getElementById('cosmos');const gl=canvas.getContext('webgl',{antialias:true,alpha:false});
const V=`attribute vec2 p;varying vec2 uv;void main(){uv=p*.5+.5;gl_Position=vec4(p,0.,1.);}`;
const F=`precision highp float;varying vec2 uv;uniform float t;uniform vec2 res;uniform vec4 pad;uniform vec3 aura;uniform float drift;float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5);}float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}float fbm(vec2 p){float v=0.,a=.5;for(int i=0;i<5;i++){v+=a*n(p);p*=2.03;a*=.52;}return v;}void main(){vec2 q=(gl_FragCoord.xy-.5*res)/min(res.x,res.y);float r=length(q);float ang=atan(q.y,q.x);float warp=sin(ang*8.+t*.7+pad.x*4.)*.04+pad.z*.08;vec2 p=q*(1.+warp+r*.25);float neb=fbm(p*3.+vec2(t*.03+pad.x,t*.02-pad.y));float rings=sin((r+pad.w*.08)*42.-t*2.2)*.5+.5;float stars=pow(max(0.,n(p*340.+t*.01)-.965),8.)*42.;vec3 col=mix(vec3(.02,.04,.09),aura,neb*.45);col+=aura*rings*smoothstep(.75,.05,r)*.14;col+=vec3(.8,.9,1.)*stars;col+=vec3(1.,.5,.2)*pow(max(0.,.018/abs(r-.34-drift*.1)),.35)*.05;gl_FragColor=vec4(pow(col,vec3(.8)),1.);}`;
function sh(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s));return s}const pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,V));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,F));gl.linkProgram(pr);const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const lp=gl.getAttribLocation(pr,'p'),lt=gl.getUniformLocation(pr,'t'),lr=gl.getUniformLocation(pr,'res'),lpad=gl.getUniformLocation(pr,'pad'),la=gl.getUniformLocation(pr,'aura'),ld=gl.getUniformLocation(pr,'drift');let aura=[1,.72,.3],pad=[0,0,0,0],drift=0;function resize(){canvas.width=innerWidth*devicePixelRatio;canvas.height=innerHeight*devicePixelRatio;gl.viewport(0,0,canvas.width,canvas.height)}addEventListener('resize',resize);resize();export function setAura(hex){const x=parseInt(hex.slice(1),16);aura=[((x>>16)&255)/255,((x>>8)&255)/255,(x&255)/255]}export function setPadState(s,d){pad=[s.lx||0,s.ly||0,s.rx||0,s.rt||0];drift=d||0}function frame(now){gl.useProgram(pr);gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.enableVertexAttribArray(lp);gl.vertexAttribPointer(lp,2,gl.FLOAT,false,0,0);gl.uniform1f(lt,now*.001);gl.uniform2f(lr,canvas.width,canvas.height);gl.uniform4fv(lpad,pad);gl.uniform3fv(la,aura);gl.uniform1f(ld,drift);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);requestAnimationFrame(frame)}requestAnimationFrame(frame);
